      $get(params?: Record<string, never>): Promise<Record<string, unknown>>;
      /** Update storage configuration. */
      $put(params?: { "blocksize"?: string; "bwlimit"?: string; "comstar_hg"?: string; "comstar_tg"?: string; "content"?: string; "content-dirs"?: string; "create-base-path"?: boolean; "create-subdirs"?: boolean; "data-pool"?: string; "delete"?: string; "digest"?: string; "disable"?: boolean; "domain"?: string; "encryption-key"?: string; "fingerprint"?: string; "format"?: "raw" | "qcow2" | "subvol" | "vmdk"; "fs-name"?: string; "fuse"?: boolean; "is_mountpoint"?: string; "keyring"?: string; "krbd"?: boolean; "lio_tpg"?: string; "master-pubkey"?: string; "max-protected-backups"?: number; "mkdir"?: boolean; "monhost"?: string; "mountpoint"?: string; "namespace"?: string; "nocow"?: boolean; "nodes"?: string; "nowritecache"?: boolean; "options"?: string; "password"?: string; "pool"?: string; "port"?: number; "preallocation"?: "off" | "metadata" | "falloc" | "full"; "prune-backups"?: string; "saferemove"?: boolean; "saferemove-stepsize"?: "1" | "2" | "4" | "8" | "16" | "32"; "saferemove_throughput"?: string; "server"?: string; "shared"?: boolean; "skip-cert-verification"?: boolean; "smbversion"?: "default" | "2.0" | "2.1" | "3" | "3.0" | "3.11"; "snapshot-as-volume-chain"?: boolean; "sparse"?: boolean; "subdir"?: string; "tagged_only"?: boolean; "username"?: string; "zfs-base-path"?: string }): Promise<{ "config"?: { "encryption-key"?: string }; "storage": string; "type": "btrfs" | "cephfs" | "cifs" | "dir" | "esxi" | "iscsi" | "iscsidirect" | "lvm" | "lvmthin" | "nfs" | "pbs" | "rbd" | "zfs" | "zfspool" }>;
      /** Delete storage configuration. */
      $delete(params?: Record<string, never>): Promise<null>;
