  "version": {
    /** API version details, including some parts of the global datacenter config. */
    $get(params?: Record<string, never>): Promise<{ "console"?: "applet" | "vv" | "html5" | "xtermjs"; "release": string; "repoid": string; "version": string }>;
  };
